package de.lazytv.pro.catalog; public class StreamItem implements java.io.Serializable { public final String id,name,categoryId,logo,streamUrl,tvgId; public final CatalogType type; public StreamItem(String id,String name,String categoryId,String logo,String streamUrl,String tvgId,CatalogType type){this.id=id;this.name=name;this.categoryId=categoryId;this.logo=logo;this.streamUrl=streamUrl;this.tvgId=tvgId;this.type=type;} }